      "name": "MvPowerSeries.le_weightedOrder_mul",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] (w : σ → ℕ) {f g : MvPowerSeries σ R} : MvPowerSeries.weightedOrder w f + MvPowerSeries.weightedOrder w g ≤ MvPowerSeries.weightedOrder w (f * g)",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.le_weightedOrder_prod",
      "type": " {σ : Type u_1} {R : Type u_3} [CommSemiring R] {ι : Type u_4} (w : σ → ℕ) (f : ι → MvPowerSeries σ R) (s : Finset ι) : ∑ i ∈ s, MvPowerSeries.weightedOrder w (f i) ≤ MvPowerSeries.weightedOrder w (∏ i ∈ s, f i)",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.weightedOrder_mul_ge",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] (w : σ → ℕ) {f g : MvPowerSeries σ R} : MvPowerSeries.weightedOrder w f + MvPowerSeries.weightedOrder w g ≤ MvPowerSeries.weightedOrder w (f * g)",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.le_weightedOrder_pow",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} (n : ℕ) : n • MvPowerSeries.weightedOrder w f ≤ MvPowerSeries.weightedOrder w (f ^ n)",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.min_weightedOrder_le_add",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] (w : σ → ℕ) {f g : MvPowerSeries σ R} : min (MvPowerSeries.weightedOrder w f) (MvPowerSeries.weightedOrder w g) ≤ MvPowerSeries.weightedOrder w (f + g)",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.le_weightedOrder_map",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {S : Type u_3} [Semiring S] (φ : R →+* S) : MvPowerSeries.weightedOrder w f ≤ MvPowerSeries.weightedOrder w ((MvPowerSeries.map φ) f)",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.le_weightedOrder_smul",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {a : R} : MvPowerSeries.weightedOrder w f ≤ MvPowerSeries.weightedOrder w (a • f)",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.weightedOrder_le",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {d : σ →₀ ℕ} (h : (MvPowerSeries.coeff d) f ≠ 0) : MvPowerSeries.weightedOrder w f ≤ ↑((Finsupp.weight w) d)",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    }
  ]
